function renderFoundation(){renderFoundationProgress();renderFoundationRunway();renderFoundationReferenceAtlas();renderPronunciation();renderFoundationKana();renderGrammarMap();renderConjugation();renderGrammar(grammarLevel,document.getElementById('grammarSearch')?.value||'');renderConfusions();renderSentencePuzzle();if(!currentKanaQuiz)newKanaQuiz();if(!currentSoundQuiz)playSoundQuiz()}

let __foundationControlsBound=false;
function bindFoundationControls(){
 if(__foundationControlsBound)return;__foundationControlsBound=true;
 document.querySelectorAll('[data-conj-kind]').forEach(b=>b.addEventListener('click',()=>{conjKind=b.dataset.conjKind;conjIndex=0;renderConjugation()}));
 document.querySelectorAll('[data-foundation-script]').forEach(b=>b.addEventListener('click',()=>{foundationKanaScript=b.dataset.foundationScript;document.querySelectorAll('[data-foundation-script]').forEach(x=>x.classList.toggle('active',x===b));renderFoundationKana();newKanaQuiz()}));
 document.querySelectorAll('[data-foundation-set]').forEach(b=>b.addEventListener('click',()=>{foundationKanaSet=b.dataset.foundationSet;document.querySelectorAll('[data-foundation-set]').forEach(x=>x.classList.toggle('active',x===b));renderFoundationKana();newKanaQuiz()}));
 document.querySelectorAll('[data-grammar-level]').forEach(b=>b.addEventListener('click',()=>renderGrammar(b.dataset.grammarLevel,document.getElementById('grammarSearch')?.value||'')));
 document.querySelectorAll('[data-grammar-cat]').forEach(b=>b.addEventListener('click',()=>setGrammarCategory(b.dataset.grammarCat)));
 document.getElementById('grammarSearch')?.addEventListener('input',e=>renderGrammar(grammarLevel,e.target.value));
}
bindFoundationControls();
